import { z } from "zod";

/**
 * Task schema modeling per case specifications:
 * - id: unique (auto-generated by backend)
 * - titulo: string, required (cannot be empty or whitespace)
 * - descricao: string, optional
 * - dataCriacao: timestamp in milliseconds
 */
export const taskSchema = z.object({
  id: z.string().uuid(),
  titulo: z.string().trim().min(1, "Task title is required and cannot be empty."),
  descricao: z.string().optional(),
  dataCriacao: z.number().int().positive(),
});

export type Task = z.infer<typeof taskSchema>;

/**
 * Schema for creating a new task
 */
export const createTaskSchema = z.object({
  titulo: z
    .string({
      required_error: "Task title is required.",
      invalid_type_error: "Task title must be a string.",
    })
    .trim()
    .min(1, "Task title cannot be empty.")
    .max(120, "Task title cannot exceed 120 characters."),
  descricao: z
    .string()
    .trim()
    .max(1000, "Description cannot exceed 1000 characters.")
    .optional(),
});

export type CreateTaskInput = z.infer<typeof createTaskSchema>;

/**
 * Schema for updating an existing task
 */
export const updateTaskSchema = z.object({
  id: z.string().min(1, "Task identifier is required."),
  titulo: z
    .string({
      required_error: "Task title is required.",
    })
    .trim()
    .min(1, "Task title cannot be empty.")
    .max(120, "Task title cannot exceed 120 characters."),
  descricao: z
    .string()
    .trim()
    .max(1000, "Description cannot exceed 1000 characters.")
    .optional(),
});

export type UpdateTaskInput = z.infer<typeof updateTaskSchema>;

/**
 * Schema for looking up or deleting by ID
 */
export const taskIdSchema = z.object({
  id: z.string().min(1, "Task identifier is required."),
});

/**
 * Pagination schema for the Infinite Scroll feature
 */
export const listTasksInputSchema = z.object({
  limit: z.number().min(1).max(50).default(6),
  cursor: z.string().nullish(), // ID of the last task as cursor
});

export type ListTasksInput = z.infer<typeof listTasksInputSchema>;
